"""Explicit final33 CPP reviews; preserve statutory text and guarded old revisions."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
STJ='https://www.stj.jus.br/sites/portalp/Processos/Sentenca-Estrangeira'
MJ='https://www.gov.br/mj/pt-br/assuntos/sua-protecao/cooperacao-internacional/cooperacao-juridica-internacional-em-materia-penal'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(780,'O título trata de homologação e rogatórias penais,sem afastar instrumentos internacionais aplicáveis. Integrar competência constitucional e procedimento atual de cooperação.', ['Identificar objeto: reconhecer decisão ou cumprir diligência.','Tratado aplicável e legislação atual devem ser verificados,sem presumir que toda cláusula histórica governa qualquer pedido.'], 'Não tratar tratado como autorização para afastar Constituição,garantias ou requisitos indiscriminadamente. Não certificada vigência de todo tratado bilateral.', 'Juízo pede oitiva de testemunha no exterior: identificar instrumento e canal de cooperação adequado,sem chamar isso de homologação da condenação.', 'Reconhecer efeitos de decisão estrangeira exige procedimento e pressupostos próprios,não mera carta para ouvir testemunha.', ['Rogatória e homologação são idênticas? Não.','Pode ignorar tratado aplicável por ler só o CPP? Não.'], 'Cooperação jurídica internacional','Atuação entre autoridades de Estados para atos e efeitos jurídicos no regime pertinente.',[CF,STJ,MJ])
add(781,'Ordem pública limita reconhecimento de decisões e cumprimento de diligências estrangeiras,com integração constitucional e garantias atuais.', ['Examinar conteúdo e efeitos pertinentes.','Ordem pública não é autorização para revisar indiscriminadamente todo mérito estrangeiro.'], 'Bons costumes não legitima discriminação arbitrária ou juízo moral sem fundamento constitucional. O controle deve seguir o procedimento competente.', 'Pedido estrangeiro exige diligência incompatível com garantia fundamental: a incompatibilidade deve ser examinada pelo órgão competente.', 'Discordar do resultado sem afronta relevante não transforma homologação em novo julgamento completo.', ['Todo desacordo de mérito prova ofensa à ordem pública? Não.','Garantias constitucionais importam? Sim.'], 'Ordem pública','Limite jurídico de reconhecimento e cooperação,integrado à Constituição.',[CF,STJ])
add(782,'O artigo atribui força de autenticidade ao trânsito diplomático; ele não faz dessa via a única forma atual de autenticação de documento estrangeiro.', ['Distinguir autenticidade,conteúdo e eficácia.','Regimes de tratados,dispensas eapostilamento pertinentes precisam ser identificados.'], 'Não exigir autenticação consular universal nem aceitar qualquer cópia sem o regime aplicável. Apostila não homologa o mérito da sentença.', 'Documento transmitido pela via diplomática é analisado sob a regra de autenticidade,sem concluir que a condenação já produz qualquer efeito.', 'Quando instrumento vigente admite outro modo de autenticar,é preciso aplicar suas condições,não invalidar por ausência de trânsito diplomático isolada.', ['Autenticidade equivale a homologação? Não.','Via diplomática é universalmente exclusiva hoje? Não.'], 'Autenticidade documental','Confirmação formal de origem distinta do reconhecimento dos efeitos da decisão.',[CF,STJ,MJ])
add(783,'A remessa diplomática descrita no CPP deve ser integrada aos canais atuais de cooperação e às autoridades centrais designadas no instrumento aplicável.', ['Identificar pedido ativo e Estado destinatário.','DRCI/MJSP atua na cooperação penal no regime informado pelo órgão oficial.'], 'Não ensinar remessa pessoal ao ministro como único canal em todo tratado ou confundir via diplomática com todos os mecanismos atuais.', 'Autoridade brasileira prepara pedido penal para o exterior e confere a autoridade central e requisitos indicados no instrumento aplicável.', 'Pedido sob outro instrumento pode ter fluxo próprio; não copiar o mesmo percurso burocrático por presunção.', ['Todo pedido deve seguir necessariamente um único canal histórico? Não.','Autoridade central deve ser identificada? Sim.'], 'Autoridade central','Órgão designado para receber,transmitir ou acompanhar cooperação no instrumento pertinente.',[MJ])
add(784,'Carta rogatória não é homologação de sentença. O exequatur cabe hoje ao STJ,conforme CF105I,i; a execução do exequatur é competência federal daCF109X.', ['Referências ao STF e Tribunal de Apelação são históricas.','Tradução,autenticidade e admissibilidade seguem normas e instrumentos pertinentes.','Não confundir reconhecimento de decisão com autorização de diligência.'], 'Não ensinar competência do STF ou cumprimento sempre por juiz criminal estadual. Via diplomática e relação com extradição do texto residual exigem integração; não certificadas todas as hipóteses internacionais.', 'Carta estrangeira pede citação no Brasil: distinguir exequatur noSTJ e cumprimento federal,não enviar automaticamente aoSTF.', 'Pedido de reconhecer efeitos de condenação estrangeira exige homologação adequada,em vez de tratar toda decisão como simples rogatória.', ['Exequatur é doSTF atualmente? Não;STJ.','Carta rogatória é a mesma coisa que homologação? Não.'], 'Exequatur','Autorização para cumprimento da carta rogatória no regime constitucional atual.',[CF,STJ,MJ])
add(785,'Conclusão,saneamento e devolução de rogatória seguem fluxo atual doSTJ,Justiça Federal e instrumento de cooperação aplicável.', ['Não reutilizar como órgãos atuais oSTF eTribunal de Apelação da redação antiga.','Diligência incompleta exige providência competente,sem inventar atos ou suprir defesa.'], 'Devolução histórica não pode fixar competência contra aCF. Não certificada toda regulamentação de cada canal internacional.', 'Diligência é concluída e sua documentação encaminhada pelo fluxo competente de cooperação.', 'Se falta ato essencial,a incompletude precisa ser tratada,sem presumir cumprimento integral pela mera devolução.', ['A denominação Tribunal de Apelação define hoje o fluxo universal? Não.','Devolver dispensa conferir cumprimento? Não.'], 'Devolução da rogatória','Encerramento e remessa da diligência pelo canal pertinente.',[CF,STJ,MJ])
add(786,'O cumprimento da diligência deve observar prazo fixado e eventual justa causa devidamente documentada,integrando o órgão constitucional atual.', ['Prazo razoável não significa prazo arbitrário ou indefinido.','Justificativa e comunicação devem chegar à autoridade competente no fluxo vigente.'], 'Não direcionar comunicação aoSTF apenas por referência histórica nem presumir que qualquer atraso fica automaticamente autorizado.', 'Diligência não pôde ser concluída por obstáculo comprovado; o órgão comunica justificativa e providência pertinente.', 'Demora sem causa documentada não é validada pelo simples rótulo razoável.', ['Justa causa deve ser demonstrada? Sim.','O artigo cria prorrogação automática para todo atraso? Não.'], 'Justa causa documentada','Motivo verificável para atraso,submetido à autoridade competente.',[CF,STJ])
add(787,'Homologação de decisão estrangeira é competência doSTJ. A remissão ao antigo CP7 deve ser confrontada comCP9 atual para efeitos civis e medida de segurança.', ['CP9 distingue pedido do interessado e condições dos demais efeitos.','Homologação não equivale automaticamente a toda execução de pena estrangeira.'], 'Não recuperar competência doSTF nem afirmar que o CP7 atual tem o mesmo conteúdo da remissão antiga. Outros regimes de cooperação/execução têm fundamentos próprios.', 'Interessado busca reparação civil de sentença penal estrangeira: examinar homologação noSTJ e condições doCP9.', 'Pedido de transferir execução de pena exige regime específico,não autorização universal só pelo art.787.', ['Efeitos atuais são lidos somente pelo número antigo CP7? Não.','Homologação implica prisão automática por toda pena estrangeira? Não.'], 'Correspondência da remissão','Integração do número histórico ao conteúdo legal atual pertinente.',[CF,CP,STJ])
add(788,'Os requisitos textuais de sentença penal estrangeira devem ser integrados aoCP9,à Constituição e ao procedimento vigente doSTJ/CPC,sem lista histórica universal.', ['Autoridade competente,citação,autenticidade,efeitos e tradução precisam de exame.','A página oficialSTJ remete aoCPC963 eRISTJ216C/D.','Trânsito e eficácia dependem do regime e finalidade do reconhecimento.'], 'Não exigir chancela consular como única forma em qualquer instrumento,nem dispensar requisito específico com regra genérica de outro tipo de decisão. Não certificada toda hipótese de dispensa de trânsito/tradução.', 'Pedido traz sentença de juiz competente,citação e documentação; órgão verifica requisitos e efeitos no regime aplicável,sem homologação automática pela lista.', 'Documento autenticado não sana por si citação irregular ou incompatibilidade constitucional.', ['Autenticidade elimina exame de citação? Não.','Cinco itens antigos esgotam todo regime atual? Não.'], 'Requisitos do reconhecimento','Pressupostos materiais e formais do regime vigente e da finalidade pretendida.',[CF,CP,STJ])
add(789,'O rito histórico de homologação e penas acessórias precisa ser integrado aoCP9,CF105I,i e procedimento atual doSTJ. Não ensinar os prazos antigos10/30 por residência como regra universal atual.', ['Medida de segurança e efeitos civis têm condições próprias noCP9.','STJ orienta petição eletrônica por advogado e requisitos doCPC/RISTJ.','Citação,defesa eintervenção seguem o procedimento pertinente.'], 'Não recuperar pena acessória histórica,STF,Tribunal de Apelação ou prazo porDistrito Federal automaticamente. Não certificada toda regulamentação processual específica posterior.', 'Parte apresenta pedido aoSTJ sob rito vigente; contraditório é assegurado sem impor automaticamente prazo antigo por residência noDF.', 'A medida de segurança pretendida exige seus pressupostos,não aplicação de pena acessória desaparecida apenas porque consta na redação antiga.', ['O prazo antigo10/30 é universalmente atual? Não.','Nomeação de defensor substitui necessidade de procedimento legal? Não.'], 'Rito integrado','Procedimento de reconhecimento segundo competência e normas atuais.',[CF,CP,STJ])
add(790,'Interessado nos efeitos civis de decisão penal estrangeira requer reconhecimento peranteSTJ,com integração aoCP9 eCPC. Execução da decisão homologada segue competência federal.', ['Reparação,restituição e outros efeitos civis são recorte expresso.','STJ reconhece; Justiça Federal executa no regime indicado.'], 'Não ensinar requerimento aoSTF nem tratar homologação como nova ação de condenação sobre todo mérito. Outros regimes possuem hipóteses próprias.', 'Vítima busca executar reparação reconhecida no exterior: confere homologação e posterior execução competentes.', 'Pretensão de aplicar toda pena corporal estrangeira não se resolve por um pedido de efeito civil.', ['Competência atual para homologar é doSTJ? Sim.','O artigo transforma pedido civil em execução automática de prisão? Não.'], 'Efeitos civis','Consequências patrimoniais da decisão reconhecida no regime adequado.',[CF,CP,STJ])
add(791,'Audiências e sessões extraordinárias podem atender à celeridade conforme necessidade,sem eliminar direitos processuais.', ['Distinguir calendário ordinário e necessidade extraordinária.','Compatibilizar intimação,preparação da defesa e restrições de798A.'], 'Celeridade não autoriza realizar ato no período suspenso sem hipótese legal ou surpreender defesa sem intimação pertinente.', 'Necessidade justifica sessão adicional em data permitida,com comunicações regulares.', 'Urgência genérica não dispensa fundamentar exceção do798A quando necessária.', ['Sessão extraordinária dispensa defesa? Não.','Necessidade e calendário legal importam? Sim.'], 'Sessão extraordinária','Ato adicional cabível sob requisitos e garantias processuais.')
add(792,'Publicidade é regra; restrição e local excepcional devem ter fundamento constitucional,necessidade e preservação da participação processual.', ['IntegrarCF5LX e93IX.','Intimidade e interesse social permitem restrição legal fundamentada.','Ato remoto/eletrônico e local excepcional têm regras próprias.'], 'Não decretar sigilo por mero constrangimento de autoridade ou invocar bons costumes para discriminar. Portas fechadas não eliminam defesa técnica nem fundamentação.', 'Dados íntimos legitimam restrição fundamentada de acesso,sem retirar defensor do ato.', 'Incômodo político com audiência pública não constitui sozinho motivo legítimo de segredo.', ['Publicidade é regra absoluta sem exceção? Não.','Restrição dispensa fundamentação? Não.'], 'Publicidade processual','Acesso como regra,com exceções legais integradas às garantias.',[CF])
add(793,'A etiqueta da redação histórica deve ser compatibilizada com prerrogativas profissionais,acessibilidade e condições concretas do ato.', ['O próprio parágrafo admite requerimento sentado do advogado perante juiz singular.','Postura física não substitui respeito,participação e garantias profissionais.'], 'Não criar prisão,nulidade ou punição automática pela pessoa permanecer sentada. Não certificada aqui toda disciplina profissional/regulamentação de atos remotos.', 'Advogado formula requerimento sentado perante juiz singular,na hipótese expressa; isso não é desobediência automática.', 'Pessoa com mobilidade reduzida precisa de adaptação,não coerção para cumprir gesto fisicamente inviável.', ['O CPP admite requerimento sentado no recorte do parágrafo? Sim.','Etiqueta cria tipo penal autônomo por si? Não.'], 'Etiqueta e acessibilidade','Organização do ato compatível com direitos e participação.',[CF])
add(794,'A autoridade que preside mantém a ordem e pode requisitar força pública,sob limites legais e constitucionais.', ['Identificar juiz ou presidente responsável pelo ato.','Manutenção de ordem não elimina direito de defesa nem integridade.'], 'Não tratar polícia da audiência como autorização geral de prisão,punição coletiva ou repressão de manifestação defensiva pertinente.', 'Presidente organiza entrada do público e atua proporcionalmente diante de tumulto real.', 'Pergunta pertinente do defensor não deve ser silenciada sob mero rótulo de inconveniência.', ['Poder de ordem é ilimitado? Não.','Pode requisitar força pública no recorte legal? Sim.'], 'Polícia da audiência','Direção e preservação da ordem sob competência e garantias.',[CF])
add(795,'Espectadores devem preservar regularidade do ato; retirada eeventual responsabilização exigem situação ebase legais.', ['Espectador não exerce o mesmo papel processual da parte/defensor.','Retirada não equivale automaticamente a crime ou prisão.'], 'Não ensinar prisão universal de quem protesta: tipicidade,legalidade,proporcionalidade e garantias precisam ser demonstradas.', 'Espectador provoca tumulto e recebe ordem legítima de retirada,com providência proporcional à situação.', 'Discordância sem conduta típica não autoriza inventar condenação automática por resistência.', ['Todo descumprimento equivale automaticamente a prisão criminal? Não.','Regularidade do ato deve ser protegida? Sim.'], 'Retirada do espectador','Medida de ordem distinta de condenação penal automática.',[CF])
add(796,'Comportamento inconveniente do réu exige medida fundamentada e preservação de defesa técnica e participação compatível.', ['Integrar regra especial da instrução e do júri pertinente.','Não realizar instrução contra réu sem defensor apenas pela retirada.'], 'Inconveniência não significa perda de todos os direitos; distinguir silêncio,exercício legítimo da defesa e perturbação concreta.', 'Réu perturba repetidamente o ato e providência legal mantém presença do defensor e garantias necessárias.', 'Réu exerce silêncio: isso não constitui automaticamente comportamento inconveniente que dispense sua defesa.', ['Retirada permite suprimir defensor? Não.','Silêncio é tumulto por presunção? Não.'], 'Defesa durante o ato','Preservação da assistência técnica diante de medida legítima de ordem.',[CF])
add(797,'Calendário de atos e continuidade do julgamento devem ser integrados à suspensão específica do798A e às exceções legais.', ['Texto distingue marcar sessão e continuar julgamento iniciado.','Não confundir possibilidade de ato em feriado com contagem de qualquer prazo.'], 'A permissão histórica de atos nas férias não afasta proibição atual de audiências/sessões de20dez a20jan fora das exceções.', 'Julgamento iniciado em dia útil tem regra de continuidade,que exige compatibilização com normas específicas pertinentes.', 'Agendar audiência ordinária no período protegido não se torna válido só pela frase atos nas férias.', ['797 elimina798A? Não.','Prática de ato e curso de prazo são conceitos distintos? Sim.'], 'Calendário processual','Datas permitidas e continuidade sob regras gerais e especiais.')
add(798,'A regra penal é contagem contínua,excluindo o dia inicial e incluindo vencimento,com prorrogação e causas de não curso. Integrar798A e intimação aplicável.', ['Dias úteis não substituem genericamente todos os dias corridos doCPP.','Vencimento não útil e inexistência de expediente exigem regime pertinente.','Intimação,ciência,força maior eobstáculo precisam de prova.'], 'Não dizer nunca suspende:798A e§4º são ressalvas. Intimação eletrônica,sexta-feira,feriados locais e prazos especiais exigem confirmação própria; exemplos pressupõem intimação válida e nenhum evento adicional.', 'Intimação válida ocorre na terça e prazo de cinco dias começa quarta: conta quarta,quinta,sexta,sábado,domingo; vencendo domingo,prorroga ao dia útil imediato,sem feriado ou outro evento.', 'Se o curso alcança suspensão aplicável de798A,os dias suspensos não são consumidos; saldo retoma depois,sem reinício integral automático.', ['Prazos penais são sempre contados só em dias úteis? Não.','Dia inicial é incluído? Não;regra exclui início e inclui vencimento.'], 'Prazo contínuo','Contagem corrida integrada a suspensão,prorrogação e início válido.')
add('798-a','Suspensão inclui20 de dezembro e20 de janeiro. Exceções: réu preso no processo vinculado à prisão,Maria da Penha e medida urgente fundamentada.', ['As duas datas extremas integram suspensão.','Vedadas audiências/sessões no intervalo fora das três hipóteses.','Suspender preserva saldo de prazo,não reinicia tudo como interrupção.'], 'Não excluir todo processo de pessoa presa sem vínculo com a prisão,nem declarar qualquer causa urgente sem despacho fundamentado. Redação incluída porLei14.365/2022; a data da conferência não é sua criação.', 'Prazo ordinário tem dois dias restantes ao começar suspensão: preserva saldo,retomando após o intervalo conforme calendário e regime de intimação.', 'Processo vinculado à prisão do réu está na exceção; não copiar suspensão automática do caso ordinário.', ['20jan está incluído? Sim.','Estar preso suspende automaticamente prazo de todo processo? Não;há exceção para o processo vinculado.'], 'Suspensão e saldo','Pausa que preserva dias restantes,diferente de reinício integral.')
add(799,'Atos do escrivão têm prazo textual de dois dias; sanções antigas devem ser integradas ao regime funcional e devido processo atuais.', ['Não converter mil-réis em reais por palpite.','Responsabilização não é automática e depende de regime competente.'], 'Não ensinar desconto,suspensão ou multa monetária histórica como punição atual automática por qualquer demora.', 'Servidor cumpre determinação no prazo textual; atraso justificado e eventual responsabilidade são examinados sob regime pertinente.', 'Erro de serviço não gera por si multa em valor inventado a partir de mil-réis.', ['Prazo textual é dois dias? Sim.','Pode converter multa antiga arbitrariamente em reais? Não.'], 'Prazo funcional','Marco para cumprimento de ato,distinto de sanção histórica automática.')
add(800,'Na ausência de prazo específico,o texto distingue decisões definitivas/mistas,simples e expediente:10,5 e1 dia,com conclusão,vista ejusto motivo.', ['Regra subsidiária: prazo específico prevalece.','Conclusão para juiz e vista paraMP têm recortes próprios.','Prazos impróprios não tornam atraso irrelevante nem geram nulidade automática.'], 'Não aplicar1/5/10 indiscriminadamente a decisão com prazo especial nem copiar recurso doMP como prazo de mera vista.', 'Decisão tem prazo específico em outra norma: usa-se o específico,sem aplicar dez dias por automatismo.', 'Sem prazo específico,despacho de expediente tem um dia no texto; motivo justo deve ser declarado para extensão cabível.', ['Prazo especial pode prevalecer? Sim.','Todo atraso gera nulidade automática? Não.'], 'Prazo subsidiário','Regra geral aplicável quando não há prazo específico pertinente.')
add(801,'O dispositivo contém modelo histórico de descontos por atraso; aplicação exige compatibilidade com regimes constitucionais e funcionais atuais.', ['Não descontar remuneração automaticamente.','Não eliminar tempo de serviço/promocional por simples contagem de dias sem procedimento.'], 'Não certificar sanção salarial automática contra juiz/MP como regime atual apenas pelo texto residual. Devido processo,competência e normas próprias precisam ser observados.', 'Atraso é levado ao órgão competente para apuração sob regime funcional aplicável.', 'Certidão isolada não autoriza inventar desconto salarial e perda dobrada de tempo como consequência automática.', ['801 basta para desconto automático atual? Não.','Atraso é sempre juridicamente irrelevante? Não;apurar no regime válido.'], 'Responsabilidade funcional','Apuração de deveres com competência e garantias atuais.',[CF])
add(802,'Certidão pode documentar atraso,mas o mecanismo histórico de desconto/multa não substitui regime atual de responsabilização.', ['Integrar801 e garantias de apuração.','Valor em mil-réis é referência histórica,não tabela monetária atual.'], 'Não ensinar multa de pleno direito ou desconto automático sem competência,base atual e devido processo.', 'Registro documenta atraso para providência legítima do órgão competente.', 'Enviar certidão não torna lícita sanção sem oportunidade de defesa.', ['Certidão elimina devido processo? Não.','Mil-réis deve virar multa atual por simples conversão? Não.'], 'Certificação do atraso','Documentação distinta da decisão sancionatória válida.',[CF])
add(803,'Retirada e acesso aos autos devem observar hipóteses legais,prerrogativas profissionais,sigilo e processo eletrônico atual.', ['Não negar toda consulta/carga pela proibição geral histórica.','Também não autorizar retirada indiscriminada de documento sigiloso.'], 'Acesso eletrônico não elimina autenticação ou restrições legítimas; carga legal não se confunde com extravio de autos.', 'Advogado acessa autos nas condições legais aplicáveis,sem negativa genérica baseada somente no803.', 'Autos sob sigilo exigem autorização/legitimação pertinentes,não livre disponibilização a qualquer visitante.', ['803 elimina todas as hipóteses legais de acesso? Não.','Sigilo permite compartilhar autos com qualquer pessoa? Não.'], 'Acesso e guarda dos autos','Consulta/carga legais com integridade,sigilo e responsabilidade.',[CF])
add(804,'Condenação em custas deve ser integrada à sucumbência,assistência jurídica e regimes legais de exigibilidade pertinentes.', ['Condenar em custas não é o mesmo que cobrar imediatamente de qualquer pessoa.','Gratuidade e hipóteses especiais precisam ser verificadas.'], 'Não impedir defesa nem afirmar que todo hipossuficiente sempre paga imediatamente ou nunca pode constar da condenação em custas.', 'Decisão examina custas e condição de gratuidade,separando condenação e exigibilidade.', 'Benefício reconhecido pode alterar cobrança no regime cabível,sem inventar imunidade patrimonial universal.', ['Condenação e exigibilidade são conceitos iguais? Não.','Gratuidade precisa do regime aplicável? Sim.'], 'Exigibilidade de custas','Condições para cobrança,distintas da previsão na decisão.',[CF])
add(805,'Contagem e cobrança de custas dependem de regras atuais da competência pertinente; oCPP não fornece tabela nacional completa.', ['Conferir norma válida e hipótese de cobrança.','Competência tributária/legalidade e gratuidade não desaparecem pela referência a regulamento.'], 'Não inventar valor ou cobrar com tabela revogada. Não certificadas todas as tabelas estaduais/federais.', 'Diligência sujeita a custas é calculada pela tabela vigente do órgão competente,considerando eventual benefício.', 'Tabela de outro estado não deve ser aplicada automaticamente só por existir no material.', ['OCPP fixa todos os valores? Não.','Regulamento pode ignorar base legal e gratuidade? Não.'], 'Tabela pertinente','Regra vigente do órgão e hipótese de cobrança.',[CF])
add(806,'Depósito e consequências textuais por falta de custas exigem integração ao regime da ação,recurso,gratuidade e defesa constitucional.', ['Hipossuficiência e assistência não podem ser ignoradas.','Não aplicar deserção universal em todo recurso penal.','Prova de pobreza tardia não dispensa exame de prejuízo e garantias.'], 'Não recusar prova essencial da defesa apenas por impossibilidade econômica,nem repetir o§3º como imunidade universal a nulidades. Não certificada toda regra local de preparo.', 'Defesa hipossuficiente requer diligência necessária: órgão examina assistência e garantia probatória,sem negativa automática por falta de depósito.', 'Ausência de preparo em hipótese que efetivamente o exige é examinada com regras e oportunidades pertinentes,sem generalizar a toda ação penal pública.', ['Todo recurso penal deserta por falta de custas? Não.','Dificuldade econômica elimina direito de defesa? Não.'], 'Preparo e defesa','Requisito financeiro quando cabível,integrado a assistência e garantias.',[CF])
add(807,'A referência à iniciativa judicial deve ser compatibilizada com sistema acusatório e hipóteses legais,sem neutralizar garantias por exigência de custas.', ['Juiz não pode substituir acusação na investigação.','Providência instrutória precisa de fundamento,momento e contraditório pertinentes.'], 'Não ensinar poderes ilimitados de produzir prova nem confundir esclarecimento cabível com investigação judicial substitutiva.', 'Durante instrução,juízo examina esclarecimento legalmente cabível e assegura manifestação das partes.', 'Juízo não pode assumir coleta acusatória indiscriminada apenas porque o807 permite diligência.', ['Iniciativa referida é ilimitada? Não.','Contraditório continua necessário? Sim.'], 'Iniciativa probatória delimitada','Providência compatível com função judicial e sistema acusatório.',[CF])
add(808,'Na falta do escrivão e substituto,pessoa idônea pode servir mediante nomeação,compromisso e termo no recorte legal.', ['Ausência dos responsáveis normais é pressuposto.','Nomeação não substitui competência e regime funcional atual para todos os cargos.'], 'Não apresentar nomeação ad hoc como dispensa universal de concurso,qualificação ou controle de acesso.', 'Em ato sem escrivão nem substituto,autoridade formaliza nomeação idônea e compromisso pertinente.', 'Pessoal disponível regularmente não é afastado sem causa só para nomear conhecido da autoridade.', ['Compromisso e termo são previstos? Sim.','A regra autoriza qualquer investidura permanente sem concurso? Não.'], 'Escrivão ad hoc','Designação excepcional no ato,sujeita a pressupostos e formalização.',[CF])
add(809,'Estatística criminal prevista no texto deve ser integrada à gestão de dados e órgãos atuais,com finalidade,qualidade,sigilo e proteção constitucional.', ['Boletim e remessa semestral são referências textuais históricas a integrar.','Não tratar acusado como culpado apenas por cadastro.','Dados pessoais/sensíveis não são automaticamente públicos.'], 'Não inventar competência atual pelo nome antigo da repartição nem divulgar religião,saúde ou antecedentes sem regime e finalidade legítimos. Não certificada toda regulamentação de estatísticas.', 'Órgão registra dados necessários para estatística legítima,preservando identificação e sigilo no regime pertinente.', 'Planilha pública com informações de saúde identificáveis não se legitima só pela lista do809.', ['Previsão estatística dispensa sigilo e finalidade? Não.','Cadastro equivale a condenação? Não.'], 'Estatística e proteção de dados','Informação para finalidade pública legítima sob limites e qualidade.',[CF])
add(810,'OCPP original entrou em vigor em1º de janeiro de1942. Essa data não é a vigência de toda alteração posterior.', ['Diploma original:1941;entrada em vigor:1942.','Separar atualização normativa e conferência editorial de criação doCódigo.'], 'Não ensinar cláusula histórica como início da regra do798A de2022 ou de qualquer lei posterior.', 'Cláusula original indica1/1/1942,enquanto mudança posterior exige sua própria regra temporal.', 'Data de revisão de2026 não altera data original de vigência.', ['Todas as alterações vigoram desde1942? Não.','É tipo penal ou obrigação processual nova de2026? Não.'], 'Vigência original','Marco histórico doCódigo,distinto das alterações posteriores.')
add(811,'Cláusula final revoga disposições em contrário no contexto da criação doCPP; não elimina automaticamente todas as leis especiais futuras.', ['Identificar conflito e sucessão normativa concretos.','Cláusula não é tipo penal autônomo nem autorização para ignorar legislação posterior.'], 'Não declarar revogação de qualquer lei especial só pela frase final de1941. Normas posteriores e especiais exigem integração.', 'Conflito é analisado segundo hierarquia,especialidade e sucessão pertinentes.', 'Lei especial posterior não desaparece automaticamente por estar fora doCPP.', ['811 revoga universalmente leis futuras? Não.','É cláusula histórica de encerramento? Sim.'], 'Cláusula revogatória','Disposição final cuja aplicação exige conflito e contexto normativos.')
assert len(rows)==33
# Answered exercises are individually written; avoid bare yes/no drills.
questions = {
780: ['Uma carta para ouvir testemunha no exterior homologa a condenação? Não. É pedido de diligência; reconhecimento dos efeitos da sentença tem objeto e procedimento próprios.', 'O título do CPP permite ignorar tratado aplicável? Não. O próprio artigo ressalva convenções e tratados, integrados à Constituição e às normas atuais.'],
781: ['Basta discordar da conclusão estrangeira para negar reconhecimento? Não. O limite de ordem pública não transforma o procedimento em nova apreciação irrestrita do mérito.', 'Bons costumes autorizam discriminação arbitrária? Não. A expressão histórica deve ser interpretada sob direitos e garantias constitucionais.'],
782: ['Autenticidade diplomática já torna a sentença executável? Não. Confirmar a origem documental é diferente de reconhecer seus efeitos jurídicos.', 'Todo documento estrangeiro exige a mesma legalização consular? Não. O instrumento e o canal de cooperação aplicáveis podem prever tratamento próprio; a orientação do MJ distingue a tramitação por autoridade central.'],
783: ['O DRCI substitui o tribunal no julgamento do pedido? Não. A autoridade central exerce funções técnicas e administrativas de cooperação, distintas da atividade jurisdicional.', 'A remessa diplomática é o único canal possível hoje? Não. É necessário conferir o instrumento internacional e as orientações da autoridade central, sem universalizar o fluxo histórico.'],
784: ['O STF concede atualmente exequatur às cartas rogatórias? Não. A CF, art. 105, I, i, atribui essa competência ao STJ desde a EC 45/2004.', 'Depois do exequatur, toda carta deve ser cumprida por juiz estadual? Não. A CF, art. 109, X, atribui a execução à Justiça Federal; não repetir o percurso histórico do CPP.'],
785: ['A devolução dispensa verificar diligência incompleta? Não. O artigo prevê completar diligências e sanar nulidades, integrado ao fluxo constitucional atual.', 'Tribunal de Apelação é o órgão constitucional atual obrigatório desse fluxo? Não. A denominação é histórica; observar STJ, Justiça Federal e o canal pertinente.'],
786: ['O exequatur fixa sempre um número uniforme de dias? Não. O texto prevê prazo razoável fixado no despacho, conforme a diligência.', 'Qualquer demora é automaticamente permitida? Não. A exceção depende de justa causa consignada e comunicação no fluxo competente atual.'],
787: ['A remissão ao antigo CP 7 corresponde ao art. 7 atual? Não. A matéria dos efeitos de sentença estrangeira está no CP 9; a numeração histórica precisa de integração.', 'Homologação para reparação civil autoriza qualquer prisão estrangeira automaticamente? Não. O CP 9 separa efeitos civis e medida de segurança; outros regimes de execução dependem de fundamentos específicos.'],
788: ['Uma autenticação regular sana citação inválida? Não. Autenticidade documental e regularidade da citação são requisitos distintos de reconhecimento.', 'Os cinco incisos históricos bastam para certificar todo pedido atual? Não. Integrar CP 9, Constituição, CPC e Regimento do STJ, observando a finalidade e o regime aplicável.'],
789: ['O prazo histórico de dez ou trinta dias conforme residência é universal hoje? Não. O rito atual do STJ deve ser consultado; não usar a distinção antiga como prazo geral vigente.', 'A menção a pena acessória restaura o regime antigo do CP? Não. Efeitos e medidas dependem do CP atual e de seus pressupostos; o texto residual não cria sanção desaparecida.'],
790: ['A vítima deve pedir homologação ao STF para efeitos civis? Não. A competência passou ao STJ; a remissão histórica deve ser lida com a Constituição atual.', 'Reconhecida a sentença, sua execução cabe genericamente ao juízo estadual? Não. A CF 109, X, e a orientação oficial do STJ situam a execução na Justiça Federal.'],
791: ['Sessão extraordinária dispensa intimação e defesa? Não. A finalidade de acelerar o andamento não elimina as garantias processuais.', 'É possível ignorar o art. 798-A porque a sessão é extraordinária? Não. O calendário deve respeitar a vedação e suas exceções expressas.'],
792: ['Todos os atos processuais são secretos por conveniência do juiz? Não. Publicidade é regra; restrição exige hipótese legítima e fundamentação constitucional.', 'Portas fechadas permitem excluir automaticamente o defensor? Não. A restrição de público não elimina participação e defesa técnica.'],
793: ['O próprio CPP admite requerimento sentado do advogado perante juiz singular? Sim. É a hipótese expressa no parágrafo único; a postura, por si, não configura desobediência.', 'Uma limitação física autoriza coerção para cumprir gesto inviável? Não. A organização do ato deve preservar participação e acessibilidade compatíveis com as garantias constitucionais.'],
794: ['A polícia da audiência é a investigação do crime? Não. A expressão designa direção e manutenção da ordem do ato pelo juiz ou presidente.', 'Requisitar força pública permite suprimir qualquer pergunta defensiva? Não. O poder de ordem tem limites legais e não elimina defesa pertinente.'],
795: ['Todo espectador retirado está automaticamente condenado por resistência? Não. A medida de ordem é distinta da apuração de eventual crime, que exige pressupostos próprios.', 'O artigo autoriza o público a interromper livremente a audiência? Não. O texto restringe manifestações dos espectadores e prevê retirada, sob limites constitucionais.'],
796: ['O ato pode prosseguir sem defensor apenas porque o réu se comportou inconvenientemente? Não. O texto preserva expressamente a assistência do defensor.', 'Exercer silêncio equivale automaticamente a perturbar a audiência? Não. Silêncio é garantia; comportamento inconveniente exige situação concreta, sem punição pelo exercício de direito.'],
797: ['Pode-se marcar normalmente sessão de julgamento para domingo pelo art. 797? Não. O texto ressalva as sessões, que não serão marcadas para domingo ou feriado.', 'Todo julgamento iniciado em dia útil para automaticamente no domingo? Não. O texto prevê continuidade, integrada às regras especiais, inclusive ao art. 798-A.'],
798: ['O CPP conta genericamente apenas dias úteis? Não. A regra geral é de dias contínuos, com exclusão do começo, inclusão do vencimento e exceções de suspensão/prorrogação.', 'Cinco dias após intimação válida na terça vencem necessariamente no domingo? Não. Na hipótese sem feriado ou evento adicional, a contagem alcança domingo e o vencimento é prorrogado ao dia útil imediato.'],
'798-a': ['Vinte de janeiro integra a suspensão ordinária? Sim. O intervalo legal inclui as duas datas extremas, de 20 de dezembro a 20 de janeiro.', 'Toda pessoa presa faz qualquer processo seu escapar da suspensão? Não. O inciso I exige processo vinculado àquela prisão; os demais incisos têm hipóteses próprias.'],
799: ['Qual é o prazo textual para atos determinados ou ordenados ao escrivão? Dois dias. Essa regra não autoriza converter arbitrariamente em reais a multa histórica em mil-réis.', 'Qualquer atraso gera automaticamente a sanção monetária antiga? Não. Responsabilização funcional deve observar competência, regime atual e garantias de apuração.'],
800: ['Qual prazo subsidiário cabe ao despacho de expediente? Um dia. A regra só se aplica quando outro prazo específico não estiver estabelecido.', 'O motivo justo permite qualquer extensão indefinida? Não. O §3º prevê exceder por igual tempo mediante motivo declarado, integrado às garantias e regras especiais.'],
801: ['Uma certidão de atraso basta para desconto automático na remuneração atual? Não. O modelo histórico deve ser integrado às normas constitucionais e ao procedimento funcional competente.', 'A cautela sobre desconto torna irrelevante todo atraso? Não. O dever de celeridade permanece e eventual responsabilidade exige apuração válida.'],
802: ['Certificar atraso equivale a impor sanção definitiva? Não. Documentar o fato é distinto de decidir responsabilidade com competência e garantias atuais.', 'Quinhentos mil-réis permitem inventar valor equivalente em reais? Não. A moeda histórica não constitui tabela atual de multas por conversão arbitrária.'],
803: ['O art. 803 proíbe todas as formas de consulta ou carga? Não. O próprio dispositivo ressalva casos legais; integrar prerrogativas, sigilo e regras atuais de acesso.', 'Acesso eletrônico permite retirar ou divulgar livremente autos sigilosos? Não. Consulta e guarda continuam sujeitas à legitimação, integridade e restrições válidas.'],
804: ['Condenação em custas equivale sempre a cobrança imediata? Não. A previsão na decisão é distinta da exigibilidade, que depende do regime e de eventual gratuidade.', 'A condição econômica pode ser ignorada em qualquer cobrança? Não. Assistência jurídica e regras de gratuidade/exigibilidade precisam ser examinadas no caso.'],
805: ['O CPP fornece uma única tabela com todos os valores nacionais? Não. O artigo remete às regras pertinentes da União e dos Estados; conferir a tabela vigente e a hipótese de cobrança.', 'Uma tabela revogada pode ser usada por estar no material antigo? Não. Cobrança exige base atual e compatibilidade com competência, legalidade e eventual gratuidade.'],
806: ['Todo recurso criminal é deserto por falta de custas? Não. O recorte do artigo, a espécie de ação, o recurso e a gratuidade precisam ser examinados; não generalizar o texto residual.', 'O texto permite negar automaticamente prova essencial à defesa hipossuficiente? Não. A própria ressalva de pobreza e as garantias constitucionais exigem análise pertinente, sem exclusão automática.'],
807: ['Determinar diligência de ofício significa substituir livremente a acusação? Não. O art. 807 deve ser integrado ao sistema acusatório e aos limites legais da atividade judicial.', 'A remissão às custas elimina contraditório sobre a prova? Não. A questão financeira não suprime garantias nem transforma o juiz em investigador acusatório.'],
808: ['A nomeação excepcional prescinde de compromisso e termo? Não. O artigo exige pessoa idônea, nomeação, compromisso perante a autoridade e termo correspondente.', 'A regra dispensa concurso para qualquer investidura permanente? Não. Seu recorte é a falta ou impedimento do escrivão e substituto no ato, integrado ao regime funcional atual.'],
809: ['Todos os dados do boletim criminal podem ser publicados com identificação? Não. A finalidade estatística não elimina sigilo, presunção de inocência e proteção constitucional de informações pessoais.', 'O nome histórico da repartição certifica o órgão atual competente? Não. A estrutura administrativa e regulamentação pertinentes devem ser conferidas; distinguir texto e implementação atual.'],
810: ['Toda alteração do CPP entrou em vigor em 1º de janeiro de 1942? Não. Esse é o marco do diploma original; cada lei modificadora possui sua disciplina temporal.', 'A data de conferência editorial muda a data original de vigência? Não. Revisão do conteúdo, criação do diploma e atualização normativa são marcos distintos.'],
811: ['A cláusula final revoga automaticamente toda lei especial futura? Não. Ela encerra o diploma original; conflitos posteriores exigem análise de hierarquia, especialidade e sucessão.', 'O art. 811 contém tipo penal autônomo? Não. Trata-se de cláusula revogatória, sem criação de crime ou pena própria.'],
}
for n, exercises in questions.items(): rows['art-'+str(n)]['prova'] = exercises
rows['art-784']['pontos'].append('O §3º trata do impulso pelo interessado e das despesas na hipótese de ação privada segundo a lei brasileira. Integrar instrumento aplicável, sem transformar isso em regra universal de toda cooperação.')
rows['art-787']['pontos'].append('CP 9: consequências equivalentes à lei brasileira; efeitos civis dependem de pedido do interessado. Para os demais efeitos ali previstos, tratado de extradição ou, na sua falta, requisição do Ministro da Justiça.')
rows['art-788']['pontos'].append('A equivalência de consequências com a aplicação da lei brasileira é pressuposto do CP 9 e do caput textual; não basta apenas traduzir o documento.')
rows['art-792']['pontos'].append('Sede do juízo/tribunal é a regra textual. Local excepcional por necessidade não dispensa acesso, defesa, motivação e requisitos pertinentes ao ato.')
rows['art-798']['pontos'].extend(['A certificação do término não é condição absoluta: o §2º admite prova do dia em que o prazo começou.', 'O §4º prevê impedimento do juiz, força maior e obstáculo judicial oposto pela parte contrária.', 'Salvo casos expressos, o §5º considera intimação, decisão em audiência/sessão com a parte presente e ciência inequívoca manifestada nos autos.'])
rows['art-800']['pontos'].append('O §4º prevê envio dos autos no dia do termo de conclusão/vista; a remissão sancionatória ao art. 799 não autoriza punição histórica automática.')
rows['art-806']['pontos'].append('O caput tem recorte de ação mediante queixa e ressalva o art. 32. O §1º distingue atos no interesse da defesa e acusado pobre; integrar assistência jurídica atual.')
rows['art-807']['pontos'].append('A exigência de custas do artigo anterior não impede, por si, diligência judicial legalmente cabível; isso não amplia ilimitadamente o poder probatório.')
rows['art-808']['simples']='Na falta ou impedimento do escrivão e seu substituto, pessoa idônea pode servir mediante nomeação pela autoridade, compromisso e termo no recorte legal.'
rows['art-803']['atencao'].append('ATUALIZAÇÃO judicial: a notícia oficial do STF de 23/06/2025 registra a ADI 7231, que invalidou a revogação indevida dos §§1º e 2º do art. 7º do Estatuto da Advocacia. Não ensinar desaparecimento dessas garantias pelo erro legislativo de 2022.')
rows['art-803']['remissoes'].append('https://noticias.stf.jus.br/postsnoticias/stf-invalida-norma-que-revogou-direitos-dos-advogados-por-erro-legislativo/')
rows['art-800']['pontos'] = ['DECISÃO DEFINITIVA ou interlocutória mista: dez dias; interlocutória simples: cinco; expediente: um.', 'Prazos do juiz começam da conclusão; vista do MP tem marco próprio, ressalvada a interposição de recurso.', 'Prazo especial prevalece. Motivo justo declarado permite exceder por igual tempo, não indefinidamente.']
rows['art-797']['pontos'] = ['Sessões de julgamento não são marcadas para domingo ou feriado na regra textual.', 'Julgamento iniciado em dia útil não se interrompe apenas pela superveniência de domingo ou feriado.', 'Compatibilizar atos em férias com a vedação e as exceções específicas do art. 798-A.']
rows['art-809']['pontos'].append('Separar o trimestre referido no inciso I da remessa semestral do §2º, cuja redação é da Lei 9.061/1995.')
import re
def readable(v):
 if isinstance(v,str):
  for old,new in [('OCPP','O CPP'),('eapostilamento','e apostilamento'),('eintervenção','e intervenção'),('eeventual','e eventual'),('ebase','e base'),('eobstáculo','e obstáculo'),('ejusto','e justo'),('798A','798-A'),('CF105I,i','CF, art. 105, I, i'),('CF109X','CF, art. 109, X'),('CF5LX','CF, art. 5º, LX'),('93IX','93, IX'),('CPC963','CPC 963'),('RISTJ216C/D','RISTJ 216-C/D'),('20dez','20 de dezembro'),('20jan','20 de janeiro')]: v=v.replace(old,new)
  v = re.sub(r'(?<=[A-Za-zÀ-ú])(?=\d)|(?<=[a-zà-ú])(?=[A-ZÀ-Ú])|(?<=\d)(?=[A-Za-z])',' ',v)
  v = re.sub(r'(?<!\d)\.(?=\d)',' ',v)
  v = re.sub(r'([,;:?!])(?=\S)',r'\1 ',v)
  v = re.sub(r'(?<=\w)(?=§)',' ',v)
  return v
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:readable(x) for k,x in v.items()}
 return v
for r in rows.values():
 for k in r:
  if k!='remissoes':r[k]=readable(r[k])
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n')
print(33,'explicit final CPP reviews')
